package atf.api.reporting.runtime.core;

/** DOM measurement memory and structural duration aggregation. */
final class ExtentReportDurationAggregation {
    private ExtentReportDurationAggregation() { }

    static String script() {
        return "function directCardHeader(card){if(!card||!card.children)return null;for(var i=0;i<card.children.length;i++){if(card.children[i].classList&&card.children[i].classList.contains('card-header'))return card.children[i];}return null;}"
                + "function directNode(card){var header=directCardHeader(card);return header&&header.querySelector('.card-title a.node');}"
                + "function durationBadge(card){var header=directCardHeader(card);if(!header)return null;return header.querySelector('.node-info .badge-default')||header.querySelector('.card-toolbar .badge-default')||header.querySelector('.card-toolbar .badge');}"
                + "function nodeLabel(card){var node=directNode(card);return String(node&&node.textContent||'').replace(/\\s+/g,' ').trim();}"
                + "function nodePathKey(card){var labels=[],current=card;while(current){var label=nodeLabel(current);if(label)labels.unshift(label);current=current.parentElement?current.parentElement.closest('.card'):null;}return labels.join(' > ');}"
                + "function nodeIdentity(card){var node=directNode(card);return node&&node.id?String(node.id):'';}"
                + "var atfMeasuredDurationsByNodeId=Object.create(null);"
                + "var atfMeasuredDurationsByPath=Object.create(null);"
                + "function rememberMeasuredDurations(){q('#test-view .test-list-item .test-contents .card > .card-header').forEach(function(header){var card=header.parentElement;if(!card)return;var badge=header.querySelector('.node-info .badge-default')||header.querySelector('.card-toolbar .badge-default')||header.querySelector('.card-toolbar .badge'),value=atfDurationValue(text(badge,''));if(value===null)return;var node=directNode(card),id=nodeIdentity(card),path=nodePathKey(card);if(id&&atfMeasuredDurationsByNodeId[id]===undefined)atfMeasuredDurationsByNodeId[id]=value;if(path&&atfMeasuredDurationsByPath[path]===undefined)atfMeasuredDurationsByPath[path]=value;if(node&&node.getAttribute('data-atf-measured-duration-ms')===null)node.setAttribute('data-atf-measured-duration-ms',String(value));if(card.getAttribute('data-atf-measured-duration-ms')===null)card.setAttribute('data-atf-measured-duration-ms',String(value));if(badge.getAttribute('data-atf-measured-duration-ms')!==String(value))badge.setAttribute('data-atf-measured-duration-ms',String(value));});}"
                + "function measuredNodeDuration(card){var node=directNode(card),nodeMarked=node&&node.getAttribute('data-atf-measured-duration-ms');if(nodeMarked!==null&&nodeMarked!=='')return Number(nodeMarked);var remembered=card&&card.getAttribute('data-atf-measured-duration-ms');if(remembered!==null&&remembered!=='')return Number(remembered);var id=nodeIdentity(card),idValue=id?atfMeasuredDurationsByNodeId[id]:undefined,path=nodePathKey(card),pathValue=path?atfMeasuredDurationsByPath[path]:undefined;if(idValue!==undefined)return Number(idValue);if(pathValue!==undefined)return Number(pathValue);var badge=durationBadge(card),marked=badge&&badge.getAttribute('data-atf-measured-duration-ms'),value=marked!==null?Number(marked):atfDurationValue(text(badge,''));if(card&&value!==null)card.setAttribute('data-atf-measured-duration-ms',String(value));return value;}"
                + "function durationChildVisible(card){return String(card.getAttribute('data-atf-filter-hidden')||'false')!=='true';}"
                + "function isStructuralNode(card){if(!card)return false;if(card.getAttribute('data-atf-node-role')||card.getAttribute('data-atf-scenario-id'))return true;var header=directCardHeader(card),title=String(text(header&&header.querySelector('.card-title a.node'))||'').trim().toUpperCase();return title==='SETUP'||title==='TEST BODY'||title==='TEARDOWN'||/^(GET|POST|PUT|PATCH|DELETE|HEAD) /.test(title)||/^(VALIDATE[: ]|.*VALIDATION)/.test(title)||/^(GIVEN|WHEN|THEN|AND|BUT)\\s+/.test(title);}"
                + "function directStructuralChildren(card){var accordion=card&&card.children?Array.prototype.slice.call(card.children).find(function(child){return child.classList&&child.classList.contains('accordion');}):null;return accordion?Array.prototype.slice.call(accordion.children).filter(function(child){return child.classList&&child.classList.contains('card');}).filter(isStructuralNode).filter(durationChildVisible):[];}"
                + "function directActionDuration(card){var total=0,count=0;q('.atf-ui-action-table tbody tr',card).forEach(function(row){var owner=row.closest('.card[data-atf-node-role],.card[data-atf-scenario-id]');if(owner!==card)return;var time=row.querySelector('.atf-ui-action-time'),value=atfDurationValue(text(time,''));if(value!==null){total+=value;count++;}});return {value:total,present:count>0};}"
                + "function directTransportEvidence(card){var panel=card&&card.children?Array.prototype.slice.call(card.children).find(function(child){return child.classList&&child.classList.contains('collapse');}):null;return !!(panel&&panel.querySelector('.execution-table,.helm-trace-table,.helm-request-details-content,.helm-response-details-content'));}"
                + "function setNodeDuration(card,value,source){if(value===null)return;var children=directStructuralChildren(card),actions=directActionDuration(card),container=children.length>0||actions.present,formatted=atfFormatDuration(value),badge=durationBadge(card);if((container||source==='measured')&&badge){if(text(badge,'')!==formatted)badge.textContent=formatted;if(badge.getAttribute('data-duration-ms')!==String(value))badge.setAttribute('data-duration-ms',String(value));if(badge.getAttribute('data-duration-source')!==source)badge.setAttribute('data-duration-source',source);}if(card.getAttribute('data-duration-ms')!==String(value))card.setAttribute('data-duration-ms',String(value));if(card.getAttribute('data-duration-source')!==source)card.setAttribute('data-duration-source',source);if(badge&&source==='measured'&&badge.getAttribute('data-atf-measured-duration-ms')!==String(value))badge.setAttribute('data-atf-measured-duration-ms',String(value));}"
                + "function aggregateChildDurations(card){var summary={total:0,count:0};directStructuralChildren(card).forEach(function(child){var value=aggregateNodeDuration(child);if(value!==null){summary.total+=value;summary.count++;}});return summary;}"
                + "function durationDecision(card,children){var actions=directActionDuration(card),measured=measuredNodeDuration(card),value=null,source='measured',ownAction=actions.present?actions.value:(directTransportEvidence(card)&&measured!==null?measured:0);if(children.count>0){value=Math.max(children.total,ownAction);source='aggregated';}else if(actions.present){value=actions.value;source='aggregated';}else if(measured!==null){value=measured;}return {value:value,source:source};}"
                + "function aggregateNodeDuration(card){var children=aggregateChildDurations(card),decision=durationDecision(card,children);setNodeDuration(card,decision.value,decision.source);return decision.value;}"
                + "function allScenarioCards(){var result=[],seen=[];function add(card){if(card&&seen.indexOf(card)<0){seen.push(card);result.push(card);}}classItems().forEach(function(root){directScenarioCards(root).forEach(add);});q('.test-view .test-content-detail .test-contents > .mt-4 > .accordion > .card').forEach(add);return result;}"
                + "function aggregateVisibleNodeDurations(){q('#test-view .test-content-detail .card').filter(function(card){return card.getAttribute('data-atf-node-role')==='phase';}).forEach(function(card){aggregateNodeDuration(card);});}"
                + "function aggregateNodeDurations(){testItems();rememberMeasuredDurations();allScenarioCards().forEach(function(card){aggregateNodeDuration(card);});aggregateVisibleNodeDurations();}";
    }
}
